import re

# Check what identifiers are considered 'numeric'
def is_numeric_identifier(s):
    '''Check if identifier is purely numeric (no letters or hyphens)'''
    return bool(re.match(r'^[0-9]+\$', s))

def validate_prerelease(prerelease):
    '''Validate prerelease identifiers'''
    if prerelease is None:
        return True
    identifiers = prerelease.split('.')
    for ident in identifiers:
        if not ident:  # empty identifier
            return False
        if is_numeric_identifier(ident):
            # Must not have leading zeros (except for '0' itself)
            if len(ident) > 1 and ident[0] == '0':
                return False
    return True

# Test cases
test_ids = ['0', '00', '1', '123', 'alpha', 'alpha-1', 'rc.1', 'x.7.z.92']
for id_ in test_ids:
    print(f'{id_:15} -> {validate_prerelease(id_)}')"
